// Helper function to draw a petal
function drawPetal(petal) {
    ctx.save();
    ctx.translate(petal.x, petal.y);
    ctx.rotate(petal.rotation);
    ctx.fillStyle = HIGHLIGHT;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(petal.width, 0);
    ctx.lineTo(petal.width, -petal.height);
    ctx.lineTo(0, -petal.height);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
}

