for(let i = 0; i < 15; i++) {
    const x = 20 + Math.random() * 360;
    const y = 300 + Math.random() * 40;
    const size = 15 + Math.random() * 25;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + size * Math.cos(0), y + size * Math.sin(0));
    ctx.lineTo(x + size * Math.cos(Math.PI/3), y + size * Math.sin(Math.PI/3));
    ctx.lineTo(x + size * Math.cos(Math.PI/3) + size * Math.cos(-Math.PI/6), y + size * Math.sin(Math.PI/3) + size * Math.sin(-Math.PI/6));
    ctx.lineTo(x + size * Math.cos(Math.PI/6), y + size * Math.sin(Math.PI/6));
    ctx.closePath();
    ctx.fill();
}

// Draw fish
function drawFish(x, y, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - 20, y - 10);
    ctx.lineTo(x - 30, y);
    ctx.lineTo(x - 20, y + 10);
    ctx.lineTo(x, y);
    ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(x - 15, y - 5);
    ctx.lineTo(x - 25, y);
    ctx.lineTo(x - 15, y + 5);
    ctx.fill();
}

