        const cy = y + Math.sin(angle) * size;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        for(let k = 0; k < 12; k++) {
            const a = k * Math.PI / 6;
            const rx = cx + Math.cos(a) * (size * 0.6);
            const ry = cy + Math.sin(a) * (size * 0.6);
            ctx.lineTo(rx, ry);
        }
        ctx.closePath();
        ctx.fill();
    }
}

// Draw fish
function drawFish(x, y, scale, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.arc(x, y, scale * 2, 0, Math.PI);
    ctx.arc(x + scale * 4, y, scale * 2, 0, Math.PI);
    ctx.arc(x + scale * 8, y, scale * 2, 0, Math.PI);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(x - scale, y);
    ctx.arc(x - scale, y, scale * 0.5, 0, Math.PI);
    ctx.arc(x - scale + scale * 0.8, y, scale * 0.5, 0, Math.PI);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x + scale * 8, y);
    ctx.arc(x + scale * 8, y, scale * 1.5, 0, Math.PI);
    ctx.arc(x + scale * 12, y, scale * 1.5, 0, Math.PI);
    ctx.closePath();
    ctx.fill();
}

