const maxRadius = Math.min(W, H) / 2 - 20;

// Define colors
const colors = [
  '#ffd166', // pastel orange
  '#4fc3f7', // pastel blue
  '#81d4fa', // pastel cyan
  '#4dd759', // pastel green
  '#ff9800', // pastel orange
  '#ff5722', // pastel red
  '#9e9e9e'  // pastel gray
];

// Draw circles with gradient effect
for (let r = 20; r <= maxRadius; r += 20) {
  const startColor = colors[Math.floor(Math.random() * colors.length)];
  const endColor = colors[(Math.floor(Math.random() * colors.length) + 1) % colors.length];

  const gradient = ctx.createLinearGradient(
    centerX - r, centerY - r,
    centerX + r, centerY + r
  );

  gradient.addColorStop(0, startColor);
  gradient.addColorStop(1, endColor);

  ctx.beginPath();
  ctx.arc(centerX, centerY, r, 0, Math.PI * 2);
  ctx.fillStyle = gradient;
  ctx.fill();

  // Add subtle border to each circle
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.stroke();
}

// Draw radial patterns
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const x = centerX + Math.cos(angle) * maxRadius;
  const y = centerY + Math.sin(angle) * maxRadius;

  // Create a small pattern
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);

  // Inner circle
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(0, 0, 15, 0, Math.PI * 2);
  ctx.fill();

  // Outer circle
  ctx.beginPath();
  ctx.arc(0, 0, 25, 0, Math.PI * 2);
  ctx.fillStyle = '#f5f5f5';
  ctx.fill();

  // Lines
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 1;
  for (let j = 0; j < 8; j++) {
    const subAngle = (j / 8) * Math.PI * 2;
    const startX = Math.cos(subAngle) * 25;
    const startY = Math.sin(subAngle) * 25;
    const endX = Math.cos(subAngle) * 35;
    const endY = Math.sin(subAngle) * 35;

    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();
  }

  ctx.restore();
}

