// Draw checkerboard pattern
function drawSquare(x, y, size, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, size, size);
}

function drawMarble(x, y, size, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, size/2, 0, Math.PI * 2);
    ctx.fill();

    // Marble center
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(x, y, size/4, 0, Math.PI * 2);
    ctx.fill();
}

function drawMarbleChessBoard() {
    const squareSize = 50;
    const boardWidth = 300;
    const boardHeight = 300;

    // Draw checkerboard
    for (let row = 0; row < 8; row++) {
        for (let col = 0; col < 8; col++) {
            if ((row + col) % 2 === 0) {
                drawSquare(col * squareSize, row * squareSize, squareSize, '#fff');
            } else {
                drawSquare(col * squareSize, row * squareSize, squareSize, '#000');
            }
        }
    }

    // Draw marbles (simplified representation)
    const marbles = [
        {x: 50, y: 50, size: 20, color: '#ff0000'},  // Red
        {x: 100, y: 100, size: 20, color: '#00ff00'}, // Green
        {x: 150, y: 150, size: 20, color: '#0000ff'}, // Blue
        {x: 200, y: 200, size: 20, color: '#ffff00'} // Yellow
    ];

    marbles.forEach(marble => {
        drawMarble(marble.x, marble.y, marble.size, marble.color);
    });
}

